diff --git a/lib/matching/__tests__/write-paths-parity.test.ts b/lib/matching/__tests__/write-paths-parity.test.ts
new file mode 100644
index 00000000..32c00213
--- /dev/null
+++ b/lib/matching/__tests__/write-paths-parity.test.ts
@@ -0,0 +1,316 @@
+/**
+ * Parity test — B.2 write-path convergence
+ *
+ * Both `computeAndPersistMatches` (background precompute path) and
+ * `persistSessionMatches` (live session path) must write identical values for
+ * the 21 non-identity, non-timestamp columns so a match renders identically
+ * regardless of which writer saved it.
+ *
+ * Columns compared:
+ *   cargo_type, load_port, discharge_port, laycan_start, laycan_end, vessel_dwt,
+ *   tce_usd_per_day, distance_nm, freight_rate_usd_per_mt, freight_rate_source,
+ *   vessel_name, cargo_ref, reason_structured,
+ *   fit_percent, fit_breakdown (non-null + same fitPercent),
+ *   cargo_item_index, vessel_item_index,
+ *   worksheet_json (both null or both non-null),
+ *   consumption_estimated, ballast_distance_nm, breakeven_tce_usd_per_day
+ *
+ * analyzePairs is mocked to return a Match with all fields populated so both
+ * paths see identical input and the comparison is meaningful.
+ */
+
+import Database from 'better-sqlite3';
+import migration032 from '@/lib/migrations/032-matches';
+import migration033 from '@/lib/migrations/033-matches-score-breakdown';
+import migration034 from '@/lib/migrations/034-matches-unique-constraint';
+import migration035 from '@/lib/migrations/035-matches-tce-distance';
+import migration036 from '@/lib/migrations/036-matches-freight-rate';
+import migration041 from '@/lib/migrations/041-matches-vessel-name';
+import migration042 from '@/lib/migrations/042-matches-fit';
+import migration044 from '@/lib/migrations/044-matches-item-index';
+import migration045 from '@/lib/migrations/045-matches-worksheet';
+import migration046 from '@/lib/migrations/046-matches-consumption-estimated';
+import migration047 from '@/lib/migrations/047-matches-ballast-distance';
+import migration050 from '@/lib/migrations/050-matches-breakeven';
+import { computeAndPersistMatches } from '@/lib/matching/compute-matches';
+import { persistSessionMatches } from '@/lib/matching/persist-session-matches';
+import { listMatches } from '@/lib/matching/matches-repository';
+import type { Match, ParsedCargo, ParsedVessel, FitBreakdown } from '@/lib/types';
+
+jest.mock('@/lib/matching/pair-analyzer', () => ({
+  analyzePairs: jest.fn(),
+}));
+
+import { analyzePairs } from '@/lib/matching/pair-analyzer';
+
+const CARGO_EMAIL_ID = 'parity-cargo-1';
+const VESSEL_EMAIL_ID = 'parity-vessel-1';
+
+function freshDb(): Database.Database {
+  const db = new Database(':memory:');
+  migration032.up(db);
+  migration033.up(db);
+  migration034.up(db);
+  migration035.up(db);
+  migration036.up(db);
+  migration041.up(db);
+  migration042.up(db);
+  migration044.up(db);
+  migration045.up(db);
+  migration046.up(db);
+  migration047.up(db);
+  migration050.up(db);
+  return db;
+}
+
+const CARGO: ParsedCargo = {
+  emailId: CARGO_EMAIL_ID,
+  itemIndex: 0,
+  originPort: { value: 'Hamburg', confidence: 'confirmed' },
+  destinationPort: { value: 'Singapore', confidence: 'confirmed' },
+  cargoType: 'BULK',
+  cargoDescription: { value: 'grain cargo', confidence: 'confirmed' },
+  laycan: '1-15 Jul 2026',
+  freightRateUsd: 25,
+  weightMt: { value: 50000, confidence: 'confirmed' },
+  weightMtMin: null,
+  weightMtMax: null,
+  volumeCbm: null,
+  dimensions: null,
+  containerType: null,
+  quantity: null,
+  incoterms: null,
+  preferredDates: null,
+  loadingRate: null,
+  dischargeRate: null,
+  commissionPercent: null,
+  commissionTerms: null,
+  specialRequirements: null,
+  stowageFactor: null,
+  missingInfo: [],
+  originCountry: null,
+  destinationCountry: null,
+};
+
+const VESSEL: ParsedVessel = {
+  emailId: VESSEL_EMAIL_ID,
+  itemIndex: 0,
+  vesselName: { value: 'MV PARITY', confidence: 'confirmed' },
+  dwtSummer: { value: 55000, confidence: 'confirmed' },
+  imo: null,
+  flag: null,
+  built: null,
+  classSociety: null,
+  pandi: null,
+  dwcc: null,
+  draftMax: null,
+  loa: null,
+  beam: null,
+  grt: null,
+  nrt: null,
+  holdsCount: null,
+  hatchesCount: null,
+  grainCapacity: null,
+  grainCapacityUnit: null,
+  baleCapacity: null,
+  holdDimensions: null,
+  hatchDimensions: null,
+  tankTopStrength: null,
+  geared: null,
+  craneCapacity: null,
+  hatchType: null,
+  vesselType: null,
+  openPosition: { value: 'Hamburg', confidence: 'confirmed' },
+  openDate: null,
+  direction: null,
+  restrictions: [],
+  lastCargoes: null,
+  speedLaden: '13',
+  speedBallast: null,
+  consumption: '28',
+  deckCapacity: null,
+  specialFeatures: [],
+};
+
+const SAMPLE_FIT_BREAKDOWN: FitBreakdown = {
+  components: [
+    { factor: 'utilisation', label: 'Size / utilisation', weight: 25, score: 22, rationale: '88% utilisation' },
+    { factor: 'timing', label: 'Timing', weight: 20, score: 18, rationale: 'ideal timing' },
+    { factor: 'ballast', label: 'Ballast distance', weight: 20, score: 14, rationale: '0nm ballast' },
+    { factor: 'classFit', label: 'Class fit', weight: 12, score: 10, rationale: 'Supramax' },
+    { factor: 'cargoType', label: 'Cargo type', weight: 8, score: 7, rationale: 'grain' },
+    { factor: 'cranes', label: 'Cranes', weight: 8, score: 6, rationale: 'geared' },
+    { factor: 'volume', label: 'Volume / stowage', weight: 4, score: 3, rationale: 'ok' },
+    { factor: 'draft', label: 'Draft', weight: 3, score: 2, rationale: 'ok' },
+  ],
+  totalWeight: 100,
+  fitPercent: 82,
+  partCargo: false,
+  vesselClass: 'supramax',
+  sanctionsPenalty: 0,
+  appliedCap: null,
+  inputs: {
+    distanceNm: 8400,
+    gapDays: 3,
+    verdict: 'ideal',
+    utilisation: 0.88,
+    vesselDwt: 55000,
+    cargoWtMax: 50000,
+  },
+};
+
+const FULL_MATCH: Match = {
+  cargoEmailId: CARGO_EMAIL_ID,
+  cargoItemIndex: 0,
+  vesselEmailId: VESSEL_EMAIL_ID,
+  vesselItemIndex: 0,
+  score: 85,
+  matchLevel: 'good',
+  matchReasons: ['Good DWT fit'],
+  issues: [],
+  fitPercent: 82,
+  fitBreakdown: SAMPLE_FIT_BREAKDOWN,
+};
+
+beforeEach(() => {
+  jest.clearAllMocks();
+});
+
+describe('write-paths parity — 21 columns (B.2)', () => {
+  it('compute-matches and persist-session-matches write identical values for all 21 columns', async () => {
+    const db = freshDb();
+
+    // Mock analyzePairs to return the same match for both paths
+    (analyzePairs as jest.Mock).mockResolvedValue({
+      matches: [FULL_MATCH],
+      blockedMatches: [],
+    });
+
+    // Path A: computeAndPersistMatches (background precompute)
+    await computeAndPersistMatches([CARGO], [VESSEL], 'session-compute', db);
+
+    // Path B: persistSessionMatches (live session path) — different session so no dedup conflict
+    persistSessionMatches(db, 'session-persist', [FULL_MATCH], [CARGO], [VESSEL]);
+
+    const [rowA] = listMatches(db, { user_id: 'session-compute', sortBy: 'score', sortDir: 'desc' });
+    const [rowB] = listMatches(db, { user_id: 'session-persist', sortBy: 'score', sortDir: 'desc' });
+
+    expect(rowA).toBeDefined();
+    expect(rowB).toBeDefined();
+
+    // 1-8: routing / cargo fields
+    expect(rowA.cargo_type).toBe(rowB.cargo_type);
+    expect(rowA.load_port).toBe(rowB.load_port);
+    expect(rowA.discharge_port).toBe(rowB.discharge_port);
+    expect(rowA.laycan_start).toBe(rowB.laycan_start);
+    expect(rowA.laycan_end).toBe(rowB.laycan_end);
+    expect(rowA.vessel_dwt).toBe(rowB.vessel_dwt);
+
+    // 9: reason_structured — both null (no scoreBreakdown on FULL_MATCH)
+    expect(rowA.reason_structured).toBeNull();
+    expect(rowB.reason_structured).toBeNull();
+
+    // 10-15: economics — both paths use computeStoredMatchEconomics
+    expect(rowA.tce_usd_per_day).not.toBeNull();
+    expect(rowA.tce_usd_per_day).toBe(rowB.tce_usd_per_day);
+    expect(rowA.distance_nm).toBe(rowB.distance_nm);
+    expect(rowA.freight_rate_usd_per_mt).toBe(rowB.freight_rate_usd_per_mt);
+    expect(rowA.freight_rate_source).toBe(rowB.freight_rate_source);
+    expect(rowA.consumption_estimated).toBe(rowB.consumption_estimated);
+    expect(rowA.ballast_distance_nm).toBe(rowB.ballast_distance_nm);
+
+    // 16: vessel_name, cargo_ref
+    expect(rowA.vessel_name).toBe(rowB.vessel_name);
+    expect(rowA.cargo_ref).toBe(rowB.cargo_ref);
+
+    // 17-18: fit columns — both must write a non-null value
+    expect(rowA.fit_percent).not.toBeNull();
+    expect(rowB.fit_percent).not.toBeNull();
+    expect(rowA.fit_breakdown).not.toBeNull();
+    expect(rowB.fit_breakdown).not.toBeNull();
+    // Both breakdowns share the same base fitPercent from FULL_MATCH
+    const fbA = JSON.parse(rowA.fit_breakdown!);
+    const fbB = JSON.parse(rowB.fit_breakdown!);
+    expect(fbA.fitPercent).toBe(fbB.fitPercent);
+
+    // 19-20: item indices
+    expect(rowA.cargo_item_index).toBe(rowB.cargo_item_index);
+    expect(rowA.vessel_item_index).toBe(rowB.vessel_item_index);
+
+    // 21: breakeven — both must be non-null (55k DWT → breakevenTceByDwt fires)
+    expect(rowA.breakeven_tce_usd_per_day).not.toBeNull();
+    expect(rowB.breakeven_tce_usd_per_day).not.toBeNull();
+    expect(rowA.breakeven_tce_usd_per_day).toBe(rowB.breakeven_tce_usd_per_day);
+  });
+
+  it('both paths write non-null worksheet_json when match has a worksheet', async () => {
+    const db = freshDb();
+
+    const matchWithWorksheet: Match = {
+      ...FULL_MATCH,
+      worksheet: {
+        readiness: {
+          openDate: '2026-07-01',
+          laycanStart: '2026-07-01',
+          laycanEnd: '2026-07-15',
+          distanceNm: 8400,
+          speedKn: 13,
+          sailingDays: 27,
+          arrivalDate: '2026-07-01',
+          gapDays: 3,
+          verdict: 'ideal',
+          explanation: 'vessel arrives within laycan',
+          openPosition: 'Hamburg',
+        },
+        vessel: {
+          draftMax: null, grainCapacity: null, grainCapacityUnit: null,
+          geared: null, vesselType: null, flag: null, built: null,
+          pandi: null, classSociety: null, lastCargoes: null,
+          dwtSummer: 55000, dwcc: null,
+        },
+        cargo: {
+          weightMt: 50000, cargoType: 'BULK',
+          loadPort: 'Hamburg', dischargePort: 'Singapore',
+        },
+        hardFilters: {
+          draft: { pass: true }, crane: { pass: true },
+          volume: { pass: true }, cargoVessel: { pass: true },
+          destDraft: { pass: true }, destCrane: { pass: true },
+          cargoWeight: { pass: true },
+        },
+      },
+    };
+
+    (analyzePairs as jest.Mock).mockResolvedValue({
+      matches: [matchWithWorksheet],
+      blockedMatches: [],
+    });
+
+    await computeAndPersistMatches([CARGO], [VESSEL], 'session-ws-compute', db);
+    persistSessionMatches(db, 'session-ws-persist', [matchWithWorksheet], [CARGO], [VESSEL]);
+
+    const [wsA] = listMatches(db, { user_id: 'session-ws-compute', sortBy: 'score', sortDir: 'desc' });
+    const [wsB] = listMatches(db, { user_id: 'session-ws-persist', sortBy: 'score', sortDir: 'desc' });
+
+    expect(wsA.worksheet_json).not.toBeNull();
+    expect(wsB.worksheet_json).not.toBeNull();
+  });
+
+  it('reason_structured is null in both paths when scoreBreakdown is absent (B.1 alignment)', async () => {
+    const db = freshDb();
+
+    (analyzePairs as jest.Mock).mockResolvedValue({
+      matches: [FULL_MATCH],
+      blockedMatches: [],
+    });
+
+    await computeAndPersistMatches([CARGO], [VESSEL], 'session-rs-compute', db);
+    persistSessionMatches(db, 'session-rs-persist', [FULL_MATCH], [CARGO], [VESSEL]);
+
+    const [rsA] = listMatches(db, { user_id: 'session-rs-compute', sortBy: 'score', sortDir: 'desc' });
+    const [rsB] = listMatches(db, { user_id: 'session-rs-persist', sortBy: 'score', sortDir: 'desc' });
+
+    expect(rsA.reason_structured).toBeNull();
+    expect(rsB.reason_structured).toBeNull();
+  });
+});
