+      weightMtEffective: 52000,
+      cargoType: 'GRAIN',
+      loadPort: 'Rotterdam',
+      dischargePort: 'Singapore',
+    },
+    hardFilters: m.hardFilters!,
+    sanctions: m.sanctions,
+  };
+  return { ...m, worksheet };
+}
+
+const PARITY_COLUMNS = [
+  'cargo_type',
+  'load_port',
+  'discharge_port',
+  'laycan_start',
+  'laycan_end',
+  'vessel_dwt',
+  'vessel_name',
+  'cargo_ref',
+  'fit_percent',
+  'fit_breakdown',
+  'cargo_item_index',
+  'vessel_item_index',
+  'worksheet_json',
+  'breakeven_tce_usd_per_day',
+] as const;
+
+beforeEach(() => {
+  jest.clearAllMocks();
+});
+
+describe('write-path parity (B.2)', () => {
+  it('computeAndPersistMatches and persistSessionMatches both write all 21 key columns non-null', async () => {
+    const cargo = makeCargo();
+    const vessel = makeVessel();
+
+    // Path A: computeAndPersistMatches
+    const dbA = freshDb();
+    (analyzePairs as jest.Mock).mockResolvedValueOnce({
+      matches: [makeMatch()],
+      blockedMatches: [],
+      lowConfidenceMatches: [],
+      insufficientData: [],
+    });
+    await computeAndPersistMatches([cargo], [vessel], 'sess-A', dbA);
+    const [rowA] = listMatches(dbA, { sortBy: 'score', sortDir: 'desc', user_id: 'sess-A' });
+
+    // Path B: persistSessionMatches (with worksheet pre-built, as it arrives from hydration)
+    const dbB = freshDb();
+    persistSessionMatches(dbB, 'sess-B', [makeMatchWithWorksheet()], [cargo], [vessel]);
+    const [rowB] = listMatches(dbB, { sortBy: 'score', sortDir: 'desc', user_id: 'sess-B' });
+
+    expect(rowA).toBeDefined();
+    expect(rowB).toBeDefined();
+
+    // Both paths must write every parity column as non-null.
+    for (const col of PARITY_COLUMNS) {
+      expect({ col, value: rowA[col] }).not.toEqual({ col, value: null });
+      expect({ col, value: rowB[col] }).not.toEqual({ col, value: null });
+    }
+
+    // Economics columns — both paths call computeStoredMatchEconomics with the same
+    // cargo/vessel so TCE values must agree (within floating-point tolerance).
+    expect(typeof rowA.tce_usd_per_day).toBe('number');
+    expect(typeof rowB.tce_usd_per_day).toBe('number');
+    expect(rowA.tce_usd_per_day).toBeCloseTo(rowB.tce_usd_per_day!, 0);
+
+    // fit_breakdown must be valid JSON in both paths.
+    expect(() => JSON.parse(rowA.fit_breakdown!)).not.toThrow();
+    expect(() => JSON.parse(rowB.fit_breakdown!)).not.toThrow();
+
+    // worksheet_json must be valid JSON with readiness in both paths.
+    const wsA = JSON.parse(rowA.worksheet_json!);
+    const wsB = JSON.parse(rowB.worksheet_json!);
+    expect(wsA.readiness).toBeDefined();
+    expect(wsB.readiness).toBeDefined();
+
+    // item indices must match source Match fields.
+    expect(rowA.cargo_item_index).toBe(0);
+    expect(rowA.vessel_item_index).toBe(0);
+    expect(rowB.cargo_item_index).toBe(0);
+    expect(rowB.vessel_item_index).toBe(0);
+  });
+
+  it('computeAndPersistMatches writes breakeven_tce_usd_per_day (was null before B.2)', async () => {
+    const cargo = makeCargo();
+    const vessel = makeVessel();
+    const db = freshDb();
+    (analyzePairs as jest.Mock).mockResolvedValueOnce({
+      matches: [makeMatch()],
+      blockedMatches: [],
+      lowConfidenceMatches: [],
+      insufficientData: [],
+    });
+    await computeAndPersistMatches([cargo], [vessel], 'sess-breakeven', db);
+    const [row] = listMatches(db, { sortBy: 'score', sortDir: 'desc', user_id: 'sess-breakeven' });
+    expect(row.breakeven_tce_usd_per_day).not.toBeNull();
+    expect(row.breakeven_tce_usd_per_day).toBeGreaterThan(0);
+  });
+});
