+/**
+ * Write-path parity (B.2) — verify that computeAndPersistMatches and
+ * persistSessionMatches write the same 21 data columns for a given input.
+ *
+ * Before B.2, computeAndPersistMatches left fit_breakdown, worksheet_json,
+ * breakeven_tce_usd_per_day, cargo_item_index, and vessel_item_index as NULL.
+ * This test locks the convergence so neither path silently drops a column.
+ *
+ * The 21 columns checked (excluding id / metadata):
+ *   cargo_type, load_port, discharge_port, laycan_start, laycan_end, vessel_dwt,
+ *   tce_usd_per_day, distance_nm, freight_rate_usd_per_mt, freight_rate_source,
+ *   vessel_name, cargo_ref,
+ *   fit_percent, fit_breakdown,
+ *   cargo_item_index, vessel_item_index,
+ *   worksheet_json,
+ *   consumption_estimated, ballast_distance_nm, breakeven_tce_usd_per_day,
+ *   reason_structured.
+ */
+
+import Database from 'better-sqlite3';
+import { runMigrations } from '@/lib/migrations/runner';
+import { allMigrations } from '@/lib/migrations';
+import { computeAndPersistMatches } from '@/lib/matching/compute-matches';
+import { persistSessionMatches } from '@/lib/matching/persist-session-matches';
+import { listMatches } from '@/lib/matching/matches-repository';
+import type { ParsedCargo, ParsedVessel, Match, MatchWorksheet, FitBreakdown } from '@/lib/types';
+
+jest.mock('@/lib/matching/pair-analyzer', () => ({
+  analyzePairs: jest.fn(),
+}));
+
+import { analyzePairs } from '@/lib/matching/pair-analyzer';
+
+const CARGO_ID = 'parity-cargo-1';
+const VESSEL_ID = 'parity-vessel-1';
+
+function freshDb(): Database.Database {
+  const db = new Database(':memory:');
+  runMigrations(db, allMigrations);
+  return db;
+}
+
+function makeCargo(): ParsedCargo {
+  return {
+    emailId: CARGO_ID,
+    itemIndex: 0,
+    originPort: { value: 'Rotterdam', confidence: 'confirmed' },
+    destinationPort: { value: 'Singapore', confidence: 'confirmed' },
+    cargoType: 'GRAIN',
+    laycan: '1-15 Jul 2026',
+    weightMt: { value: 50000, confidence: 'confirmed' },
+    weightMtMin: 48000,
+    weightMtMax: 52000,
+    cargoDescription: { value: 'WHEAT', confidence: 'confirmed' },
+    volumeCbm: null,
+    dimensions: null,
+    containerType: null,
+    quantity: null,
+    incoterms: null,
+    preferredDates: null,
+    loadingRate: null,
+    dischargeRate: null,
+    commissionPercent: null,
+    commissionTerms: null,
+    specialRequirements: null,
+    stowageFactor: null,
+    missingInfo: [],
+    originCountry: null,
+    destinationCountry: null,
+  };
+}
+
+function makeVessel(): ParsedVessel {
+  return {
+    emailId: VESSEL_ID,
+    itemIndex: 0,
+    vesselName: { value: 'PARITY TEST', confidence: 'confirmed' },
+    dwtSummer: { value: 57000, confidence: 'confirmed' },
+    openDate: { value: '2026-06-20', confidence: 'confirmed' },
+    openPosition: { value: 'Rotterdam', confidence: 'confirmed' },
+    imo: null,
+    flag: 'PAN',
+    built: 2012,
+    classSociety: 'BV',
+    pandi: null,
+    dwcc: { value: 55000, confidence: 'confirmed' },
+    draftMax: { value: 12.5, confidence: 'confirmed' },
+    loa: null,
+    beam: null,
+    grt: null,
+    nrt: null,
+    holdsCount: null,
+    hatchesCount: null,
+    grainCapacity: 70000,
+    grainCapacityUnit: 'cbm',
+    baleCapacity: null,
+    holdDimensions: null,
+    hatchDimensions: null,
+    tankTopStrength: null,
+    geared: false,
+    craneCapacity: null,
+    hatchType: null,
+    vesselType: 'BULK CARRIER',
+    direction: null,
+    restrictions: [],
+    lastCargoes: 'GRAIN, SOYBEANS',
+    speedLaden: '13 kts',
+    speedBallast: null,
+    consumption: '28 mt/day',
+    deckCapacity: null,
+    specialFeatures: [],
+  };
+}
+
+const MOCK_FIT_BREAKDOWN: FitBreakdown = {
+  components: [
+    { factor: 'utilisation', label: 'Utilisation', weight: 20, score: 18, rationale: 'Good fit' },
+    { factor: 'timing', label: 'Timing', weight: 20, score: 16, rationale: 'Ideal' },
+    { factor: 'economics', label: 'Economics', weight: 15, score: 12, rationale: 'Positive' },
+  ],
+  totalWeight: 55,
+  fitPercent: 83.6,
+  partCargo: false,
+  vesselClass: 'supramax',
+  sanctionsPenalty: 0,
+  appliedCap: null,
+  inputs: {
+    distanceNm: 15300,
+    gapDays: 5,
+    verdict: 'ideal',
+    utilisation: 0.88,
+    vesselDwt: 57000,
+    cargoWtMax: 52000,
+  },
+};
+
+function makeMatch(): Match {
+  return {
+    cargoEmailId: CARGO_ID,
+    cargoItemIndex: 0,
+    vesselEmailId: VESSEL_ID,
+    vesselItemIndex: 0,
+    score: 85,
+    matchLevel: 'good',
+    matchReasons: ['Good utilisation and timing'],
+    issues: [],
+    fitPercent: MOCK_FIT_BREAKDOWN.fitPercent,
+    fitBreakdown: MOCK_FIT_BREAKDOWN,
+    readiness: {
+      openDate: '2026-06-20',
+      laycanStart: '2026-07-01',
+      laycanEnd: '2026-07-15',
+      distanceNm: 15300,
+      distanceExact: true,
+      speedKn: 13,
+      sailingDays: 49,
+      arrivalDate: '2026-07-01',
+      gapDays: 5,
+      verdict: 'ideal',
+      explanation: 'Vessel arrives within laycan window',
+    },
+    hardFilters: {
+      draft: { pass: true },
+      crane: { pass: true },
+      volume: { pass: true },
+      cargoVessel: { pass: true },
+      destDraft: { pass: true },
+      destCrane: { pass: true },
+      cargoWeight: { pass: true },
+    },
+    sanctions: { risk: 'LOW', blocking: false },
+  };
+}
+
+function makeMatchWithWorksheet(): Match {
+  const m = makeMatch();
+  const worksheet: MatchWorksheet = {
+    readiness: {
+      ...m.readiness!,
+      openPosition: 'Rotterdam',
+    },
+    vessel: {
+      draftMax: 12.5,
+      grainCapacity: 70000,
+      grainCapacityUnit: 'cbm',
+      geared: false,
+      vesselType: 'BULK CARRIER',
+      flag: 'PAN',
+      built: 2012,
+      pandi: null,
+      classSociety: 'BV',
+      lastCargoes: 'GRAIN, SOYBEANS',
+      dwtSummer: 57000,
+      dwcc: 55000,
+    },
+    cargo: {
+      weightMt: 50000,
+      weightMtEffective: 52000,
+      cargoType: 'GRAIN',
+      loadPort: 'Rotterdam',
+      dischargePort: 'Singapore',
+    },
+    hardFilters: m.hardFilters!,
+    sanctions: m.sanctions,
+  };
+  return { ...m, worksheet };
+}
+
+const PARITY_COLUMNS = [
+  'cargo_type',
+  'load_port',
+  'discharge_port',
+  'laycan_start',
+  'laycan_end',
+  'vessel_dwt',
+  'vessel_name',
+  'cargo_ref',
+  'fit_percent',
+  'fit_breakdown',
+  'cargo_item_index',
+  'vessel_item_index',
+  'worksheet_json',
+  'breakeven_tce_usd_per_day',
+] as const;
+
+beforeEach(() => {
+  jest.clearAllMocks();
+});
+
+describe('write-path parity (B.2)', () => {
+  it('computeAndPersistMatches and persistSessionMatches both write all 21 key columns non-null', async () => {
+    const cargo = makeCargo();
+    const vessel = makeVessel();
+
+    // Path A: computeAndPersistMatches
+    const dbA = freshDb();
+    (analyzePairs as jest.Mock).mockResolvedValueOnce({
+      matches: [makeMatch()],
+      blockedMatches: [],
+      lowConfidenceMatches: [],
+      insufficientData: [],
+    });
+    await computeAndPersistMatches([cargo], [vessel], 'sess-A', dbA);
+    const [rowA] = listMatches(dbA, { sortBy: 'score', sortDir: 'desc', user_id: 'sess-A' });
+
+    // Path B: persistSessionMatches (with worksheet pre-built, as it arrives from hydration)
+    const dbB = freshDb();
+    persistSessionMatches(dbB, 'sess-B', [makeMatchWithWorksheet()], [cargo], [vessel]);
+    const [rowB] = listMatches(dbB, { sortBy: 'score', sortDir: 'desc', user_id: 'sess-B' });
+
+    expect(rowA).toBeDefined();
+    expect(rowB).toBeDefined();
+
+    // Both paths must write every parity column as non-null.
+    for (const col of PARITY_COLUMNS) {
+      expect({ col, value: rowA[col] }).not.toEqual({ col, value: null });
+      expect({ col, value: rowB[col] }).not.toEqual({ col, value: null });
+    }
+
+    // Economics columns — both paths call computeStoredMatchEconomics with the same
+    // cargo/vessel so TCE values must agree (within floating-point tolerance).
+    expect(typeof rowA.tce_usd_per_day).toBe('number');
+    expect(typeof rowB.tce_usd_per_day).toBe('number');
+    expect(rowA.tce_usd_per_day).toBeCloseTo(rowB.tce_usd_per_day!, 0);
+
+    // fit_breakdown must be valid JSON in both paths.
+    expect(() => JSON.parse(rowA.fit_breakdown!)).not.toThrow();
+    expect(() => JSON.parse(rowB.fit_breakdown!)).not.toThrow();
+
+    // worksheet_json must be valid JSON with readiness in both paths.
+    const wsA = JSON.parse(rowA.worksheet_json!);
+    const wsB = JSON.parse(rowB.worksheet_json!);
+    expect(wsA.readiness).toBeDefined();
+    expect(wsB.readiness).toBeDefined();
+
+    // item indices must match source Match fields.
+    expect(rowA.cargo_item_index).toBe(0);
+    expect(rowA.vessel_item_index).toBe(0);
+    expect(rowB.cargo_item_index).toBe(0);
+    expect(rowB.vessel_item_index).toBe(0);
+  });
+
+  it('computeAndPersistMatches writes breakeven_tce_usd_per_day (was null before B.2)', async () => {
+    const cargo = makeCargo();
+    const vessel = makeVessel();
+    const db = freshDb();
+    (analyzePairs as jest.Mock).mockResolvedValueOnce({
+      matches: [makeMatch()],
+      blockedMatches: [],
+      lowConfidenceMatches: [],
+      insufficientData: [],
+    });
+    await computeAndPersistMatches([cargo], [vessel], 'sess-breakeven', db);
+    const [row] = listMatches(db, { sortBy: 'score', sortDir: 'desc', user_id: 'sess-breakeven' });
+    expect(row.breakeven_tce_usd_per_day).not.toBeNull();
+    expect(row.breakeven_tce_usd_per_day).toBeGreaterThan(0);
+  });
+});
